// รับ rates array จาก admin.html (รุ่นรถ & ราคา)
// แต่ละ item: { submodel_name, auto_rate, auto_rate_unit, auto_down_pcts, auto_rate2, auto_rate2_min_down }
const body = $input.first().json.body || $input.first().json;
const rates = body.rates || [];

if (rates.length === 0) {
  return [{ json: { sql: 'SELECT 1;', count: 0 } }];
}

const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");

// UPDATE bike_catalog ด้วย exact submodel_name match (ไม่ใช้ LIKE)
const statements = rates.map(r =>
  `UPDATE bike_catalog SET auto_rate=${parseFloat(r.auto_rate)||0}, auto_rate_unit='${esc(r.auto_rate_unit||'month')}', auto_down_pcts='${esc(r.auto_down_pcts)}', auto_rate2=${parseFloat(r.auto_rate2)||0}, auto_rate2_min_down=${parseInt(r.auto_rate2_min_down)||0} WHERE submodel_name = '${esc(r.submodel_name)}';`
).join('\n');

return [{ json: { sql: statements, count: rates.length } }];
